import{_ as a}from"./chunks/02-model-link-create.GYs-TGFF.js";import{_ as e,o as r,c as o,a2 as i}from"./chunks/framework.z3u3TMv0.js";const n="/ultra_guides/shots/07-model-link-list.png",l="/ultra_guides/shots/08-model-settings.png",b=JSON.parse('{"title":"模型连接与参数","description":"MiniTavern BYOK 模型连接教程：填写 Base URL 与 API Key、测连、采样参数；对接云端或 Ollama/LM Studio 本地 OpenAI 兼容接口。","frontmatter":{"title":"模型连接与参数","description":"MiniTavern BYOK 模型连接教程：填写 Base URL 与 API Key、测连、采样参数；对接云端或 Ollama/LM Studio 本地 OpenAI 兼容接口。","head":[["meta",{"name":"keywords","content":"酒馆,AI酒馆,Ai酒馆,迷你酒馆,超迷你酒馆,MiniTavern,AI伙伴,AI朋友,Ai本地聊天,AI本地聊天,Silly Tavern,SillyTavern,手机玩Silly Tavern,Silly Tavern手机版,Silly Tavern安卓,Silly Tavern苹果,AI角色扮演,角色卡,角色扮演,AI聊天,手机AI,离线AI,AI剧情,本地大模型,本地模型,Ollama,LM Studio,世界书,正则,BYOK,用户手册,教程,character card,AI roleplay,AI companion,tavern AI"}],["meta",{"property":"og:title","content":"模型连接与参数 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern BYOK 模型连接教程：填写 Base URL 与 API Key、测连、采样参数；对接云端或 Ollama/LM Studio 本地 OpenAI 兼容接口。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/manual/model-link"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/manual/model-link"}]]},"headers":[],"relativePath":"manual/model-link.md","filePath":"manual/model-link.md","lastUpdated":1787117554000}'),d={name:"manual/model-link.md"};function s(p,t,h,u,c,m){return r(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="模型连接与参数" tabindex="-1">模型连接与参数 <a class="header-anchor" href="#模型连接与参数" aria-label="Permalink to &quot;模型连接与参数&quot;">​</a></h1><p>BYOK：密钥保存在本机安全存储；请求直连你配置的地址。</p><p>没有付费 API 时，可先看 <a href="/ultra_guides/free-cloud/">免费云端</a>；本机部署见 <a href="/ultra_guides/local/">部署本地模型</a>。</p><h2 id="模型连接" tabindex="-1">模型连接 <a class="header-anchor" href="#模型连接" aria-label="Permalink to &quot;模型连接&quot;">​</a></h2><p>路径：<strong>设置 → 模型 → 模型连接</strong></p><p><img src="'+n+'" alt="模型连接列表"></p><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td>新建</td><td>平台、密钥、Base URL、模型</td></tr><tr><td>编辑 / 复制 / 删除</td><td>列表右侧菜单</td></tr><tr><td>设为默认</td><td>新对话默认使用</td></tr><tr><td>测连</td><td>保存前或编辑页「测试」。须选<strong>文本聊天</strong>模型；TTS / 生图专用 ID（如 Gemini <code>*-tts</code>）会报不支持文字对话，见 <a href="./errors#textoutputunsupported">错误排错 · textOutputUnsupported</a></td></tr></tbody></table><h3 id="平台类型-常见" tabindex="-1">平台类型（常见） <a class="header-anchor" href="#平台类型-常见" aria-label="Permalink to &quot;平台类型（常见）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>选项（文案以 App 为准）</th><th>用途</th></tr></thead><tbody><tr><td>各云厂商预设</td><td>自动填国内/国际站 Base URL</td></tr><tr><td>自定义 (OpenAI 协议)</td><td>本地 Ollama / LM Studio、兼容网关</td></tr><tr><td>自定义 Gemini / Anthropic</td><td>对应协议端点</td></tr></tbody></table><p>多站点平台可切换「使用国际站」。本地模型详见 <a href="/ultra_guides/connect-app/minitavern">连接 MiniTavern</a> 与 <a href="/ultra_guides/local/tools">工具总览</a>。</p><p><img src="'+a+'" alt="新建连接"></p><h2 id="模型设置-全局参数" tabindex="-1">模型设置（全局参数） <a class="header-anchor" href="#模型设置-全局参数" aria-label="Permalink to &quot;模型设置（全局参数）&quot;">​</a></h2><p>路径：<strong>设置 → 模型设置</strong></p><p><img src="'+l+'" alt="模型设置"></p><p>常见项（名称以 App 为准）：</p><ul><li>记忆长度（历史条数相关）</li><li>回复令牌（max tokens，上限 128000；部分 Claude 场景<strong>不要</strong>设为 None）</li><li>Temperature、Top-P / Top-K</li><li>是否流式输出</li></ul><h2 id="会话级覆盖" tabindex="-1">会话级覆盖 <a class="header-anchor" href="#会话级覆盖" aria-label="Permalink to &quot;会话级覆盖&quot;">​</a></h2><p>路径：对话页 → <strong>设置</strong> → 模型连接 / 参数</p><p>可为单聊指定连接与采样，不改全局默认。</p><h2 id="聊天设置里的识图" tabindex="-1">聊天设置里的识图 <a class="header-anchor" href="#聊天设置里的识图" aria-label="Permalink to &quot;聊天设置里的识图&quot;">​</a></h2><p>路径：<strong>设置 → 聊天 → 识图设置</strong></p><p>单聊可在聊天设置 → <strong>识图与显示</strong> 跟随默认或单独覆盖（描写模型与提示词仍用全局）。</p><ul><li>关闭「图片描写」：多模态直接把图送给模型（模型需支持视觉）。</li><li>开启：先描写再主模型（描写结果会缓存复用）。</li></ul><p>若报「当前模型不支持图片」，见 <a href="./errors#visionunsupported">错误排错 · visionUnsupported</a>。</p><h2 id="生图-连接-回复图片-关键词" tabindex="-1">生图（连接 / 回复图片 / 关键词） <a class="header-anchor" href="#生图-连接-回复图片-关键词" aria-label="Permalink to &quot;生图（连接 / 回复图片 / 关键词）&quot;">​</a></h2><p>路径：<strong>设置 → 生图</strong></p><ul><li><strong>生图连接 / 生图设置</strong>：API、尺寸/质量、生成数量（仅 <code>/imagine</code>）、增强提示词（默认画质词）、负面提示词（默认低质量 / 模糊 / 多余手指 / 水印等）</li><li><strong>回复图片</strong>（在生图设置里）：先打开开关，再选触发方式。关闭后聊天不会自动出图（斜杠命令、附件菜单、长按气泡不受影响） <ul><li><strong>智能判断</strong>：由模型根据对话判断这一轮要不要出图；画幅按场景选（手机自拍 3:4，相机成片 3:2），命中后固定 1 张</li><li><strong>关键词触发</strong>：用户消息命中关键词规则时出图；画面和画幅按当前对话生成，命中后固定 1 张</li></ul></li><li><strong>关键词触发生图</strong>：配置规则。要真正触发，需在生图设置中开启回复图片并选择关键词触发</li></ul><p>聊天里生图：</p><table tabindex="0"><thead><tr><th>入口</th><th>说明</th></tr></thead><tbody><tr><td><code>/imagine 提示词</code></td><td>先经主聊天模型判断：是否与当前对话有关、要不要角色/用户参考图，再拼提示词去生图。可先点加号附图：主模型会看到这些图再写生图提示词，生图时也会当作参考；附图不会让模型跳过角色图/用户图的判断。这些图会显示在生图气泡的小预览里，不会当成一条聊天发言。张数用生图设置里的「生成数量」。失败时气泡会留下并显示重试</td></tr><tr><td><code>/imagine scene</code> / 附件 → 根据故事</td><td>按近期对话画当前这一幕，1 张</td></tr><tr><td><code>/imagine last</code> / 附件 → 根据最后消息</td><td>按最后一条消息来画，1 张</td></tr></tbody></table><p>未配置生图连接时，附件菜单四种生图模式与发送 <code>/imagine</code> 会弹出「去设置 / 取消」，不清空输入框。智能 / 关键词自动出图则为 Toast。在生图设置开启「回复图片」时若无连接会弹窗，开关保持关闭。 | 附件 → 生成背景图 | 画环境背景，1 张；完成后可设为聊天背景 | | 长按气泡 → 生图 | 按这条气泡来画，1 张 |</p><p>例子：输入「给我一张你的自拍照」会带上角色参考和对话语境；「给我一张小狗的照片」则按独立请求画，不套角色脸。</p><p>本机 A1111 / ComfyUI：<a href="/ultra_guides/local/image-gen/">生图模型部署</a> · <a href="/ultra_guides/local/image-gen/connect-app">连 App</a>。<br> 云端免费档见 <a href="/ultra_guides/free-cloud/#免费生图怎么配">免费云端 · 生图</a>。</p><h2 id="排错入口" tabindex="-1">排错入口 <a class="header-anchor" href="#排错入口" aria-label="Permalink to &quot;排错入口&quot;">​</a></h2><p>测连或聊天失败 → Toast / 气泡 → <strong>查看详情</strong>（错误代码 + 原因 + 建议）→ 对照 <a href="./errors">错误代码排错</a>。</p>',34)])])}const f=e(d,[["render",s]]);export{b as __pageData,f as default};
